package telegram

// Preparation of host-generated bytes (CP-003 PR 5).
//
// Rendered code documents and synthesized audio are not agent files, so there
// is no source path to walk. They still follow the same order as agent files so
// the same quotas, rate caps, private storage and reconciliation apply:
//
//  1. reserve the upper bound in the store (one short transaction);
//  2. outside SQL, write the bytes into a private snapshot and fsync;
//  3. mark the artifact ready with its measured hash and size.
//
// Nothing here holds a transaction across file I/O or a backend call.

import (
	"context"
	"errors"
	"fmt"
	"strings"
	"time"

	"github.com/Coriol-is/gopod/internal/artifactfs"
	"github.com/Coriol-is/gopod/internal/store"
)

// terminalWriteTimeout bounds bookkeeping writes made on a fresh context after
// the attempt context ended (cancellation must not lose an outcome).
const terminalWriteTimeout = 10 * time.Second

// PreparationStore is the part of the store byte preparation needs.
type PreparationStore interface {
	ReserveArtifacts(ctx context.Context, req store.ArtifactReservation) (store.Preparation, error)
	MarkArtifactsReady(ctx context.Context, sc store.ScopeRef, prep string, facts []store.ArtifactFacts) error
	AbandonPreparation(ctx context.Context, prep, reason string) error
	GetArtifact(ctx context.Context, id string) (store.Artifact, error)
}

// SnapshotWriter is the blob store surface byte preparation needs.
// *artifactfs.Blobs implements it.
type SnapshotWriter interface {
	NewPreparation(prep string) error
	SnapshotBytes(prep, name string, data []byte, maxBytes int64) (artifactfs.Snapshot, error)
	ReadVerified(key string, size int64, sha string, maxBytes int64) ([]byte, error)
}

// byteArtifacts reserves, writes and reads back single-file preparations.
type byteArtifacts struct {
	st       PreparationStore
	blobs    SnapshotWriter
	maxBytes int64 // per-file bound; equals the store's per-file limit
}

// open reserves upper bytes and creates the private preparation directory.
// On error nothing is left reserved. ttl <= 0 means the store default.
func (a byteArtifacts) open(ctx context.Context, sc store.ScopeRef, owner string, upper int64, ttl time.Duration) (store.Preparation, error) {
	prep, err := a.st.ReserveArtifacts(ctx, store.ArtifactReservation{Scope: sc, OwnerRef: owner, Files: 1, Bytes: upper, TTL: ttl})
	if err != nil {
		return store.Preparation{}, err
	}
	if err = a.blobs.NewPreparation(prep.ID); err != nil {
		a.release(ctx, prep.ID, "prepare_failed")
		return store.Preparation{}, fmt.Errorf("preparation directory: %w", err)
	}
	return prep, nil
}

// fill writes data as the preparation's only artifact and marks it ready. The
// returned facts are the measured hash and size of exactly data.
func (a byteArtifacts) fill(ctx context.Context, sc store.ScopeRef, prep store.Preparation, mediaType, filename string, data []byte) (store.ArtifactFacts, error) {
	_, name, ok := strings.Cut(prep.BlobKeys[0], "/")
	if !ok {
		return store.ArtifactFacts{}, errors.New("malformed blob key")
	}
	snap, err := a.blobs.SnapshotBytes(prep.ID, name, data, min(a.maxBytes, prep.Bytes))
	if err != nil {
		return store.ArtifactFacts{}, fmt.Errorf("snapshot: %w", err)
	}
	facts := store.ArtifactFacts{ArtifactID: prep.ArtifactIDs[0], SHA256: snap.SHA256, Size: snap.Size, MediaType: mediaType, Filename: filename}
	if err = a.st.MarkArtifactsReady(ctx, sc, prep.ID, []store.ArtifactFacts{facts}); err != nil {
		return store.ArtifactFacts{}, fmt.Errorf("mark ready: %w", err)
	}
	return facts, nil
}

// read returns the verified snapshot bytes of a ready artifact: the bytes that
// were hashed at preparation, never the caller's buffer.
func (a byteArtifacts) read(prep store.Preparation, facts store.ArtifactFacts) ([]byte, error) {
	return a.blobs.ReadVerified(prep.BlobKeys[0], facts.Size, facts.SHA256, a.maxBytes)
}

// release abandons a preparation on a context that survives cancellation. The
// reconciler removes the blobs; a failure here only delays that.
func (a byteArtifacts) release(ctx context.Context, prepID, reason string) {
	rctx, cancel := context.WithTimeout(context.WithoutCancel(ctx), terminalWriteTimeout)
	defer cancel()
	_ = a.st.AbandonPreparation(rctx, prepID, reason)
}
